INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Programmablaufplan immer für Programmierer gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Planung und Dokumentation genutzt"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Programmablaufplans?', 3, '[{"text": "Abläufe visualisieren", "correct": true, "because": "Veranschaulicht Logik und Schritte"}, {"text": "Code schreiben", "correct": false, "because": "Nicht direkte Programmierung"}, {"text": "Manuelle Ausführung", "correct": false, "because": "Planungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente enthält ein Programmablaufplan typischerweise?', 5, '[{"text": "Entscheidungen", "correct": true, "because": "Zeigen Verzweigungen"}, {"text": "Prozesse", "correct": true, "because": "Darstellen Schritte"}, {"text": "Farbcodes", "correct": false, "because": "Nur gestalterisch"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Programmablaufplan zeigt Ablaufstrukturen. b) Er ersetzt den Quellcode.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) dient Planung, nicht Umsetzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung eines Programmablaufplans?', 4, '[{"text": "Logische Abfolge", "correct": false, "because": "Kern der Darstellung"}, {"text": "Klarheit", "correct": false, "because": "Fördert Verständnis"}, {"text": "Bildbearbeitung", "correct": true, "because": "Irrelevant für Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Programmablaufplan immer softwaregestützt erstellt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch manuell zeichbar"}, {"text": "Ja", "correct": false, "because": "Manuelle Optionen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol steht für eine Entscheidung in einem Programmablaufplan?', 3, '[{"text": "Raute", "correct": true, "because": "Darstellt Verzweigung"}, {"text": "Kreis", "correct": false, "because": "Markiert Start/Ende"}, {"text": "Dreieck", "correct": false, "because": "Nicht standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Programmablaufplan?', 5, '[{"text": "Klarheit", "correct": true, "because": "Vereinfacht Verständnis"}, {"text": "Fehlererkennung", "correct": true, "because": "Zeigt Logikfehler"}, {"text": "Grafische Animation", "correct": false, "because": "Nicht primär"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Programmablaufpläne helfen bei der Planung. b) Sie sind nur für große Projekte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch für kleine Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Programmablaufplan?', 4, '[{"text": "Logische Schritte", "correct": false, "because": "Kern der Darstellung"}, {"text": "Standard-Symbole", "correct": false, "because": "Fördern Klarheit"}, {"text": "3D-Modellierung", "correct": true, "because": "Irrelevant für Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt ein Programmablaufplan die Programmierung?', 2, '[{"text": "Nein", "correct": true, "because": "Dient Planung, nicht Umsetzung"}, {"text": "Ja", "correct": false, "because": "Nur Vorlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Symbole sind in einem Programmablaufplan typisch?', 4, '[{"text": "Rechteck für Prozesse", "correct": true, "because": "Zeigt Verarbeitung"}, {"text": "Raute für Entscheidungen", "correct": true, "because": "Zeigt Verzweigung"}, {"text": "Stern für Design", "correct": false, "because": "Nicht standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Programmablaufpläne immer komplex sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können einfach sein"}, {"text": "Ja", "correct": false, "because": "Komplexität abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Programmablaufplan?', 3, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Viele Details", "correct": false, "because": "Kann überladen"}, {"text": "Manuelle Zeichnung", "correct": false, "because": "Tools effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Programmablaufpläne zeigen Logik. b) Sie sind nur für Programmierer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch für Planer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools helfen bei der Erstellung eines Programmablaufplans?', 5, '[{"text": "Diagrammsoftware", "correct": true, "because": "Wie Visio oder Lucidchart"}, {"text": "Zeichenprogramme", "correct": true, "because": "Wie Draw.io"}, {"text": "Texteditoren", "correct": false, "because": "Nicht visuell"}, {"text": "Musiksoftware", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Programmablaufplan unwichtig?', 3, '[{"text": "Logische Abfolge", "correct": false, "because": "Kern der Darstellung"}, {"text": "Lesbarkeit", "correct": false, "because": "Fördert Verständnis"}, {"text": "Zufällige Farben", "correct": true, "because": "Stören Klarheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Programmablaufpläne für agile Projekte geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Helfen bei Iterationen"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Programmablaufplan detaillierten Code enthalten?', 3, '[{"text": "Nein", "correct": true, "because": "Zeigt Logik, nicht Code"}, {"text": "Ja", "correct": false, "because": "Abstrakte Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Programmablaufplan?', 4, '[{"text": "Planung eines Bestellprozesses", "correct": true, "because": "Visualisiert Ablauf"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Ablaufdarstellung"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Technische Aufgabe"}]');
